pub const PIN_IDENTIFIER: &str = "$PIN";

#[inline]
pub fn pin_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PIN_IDENTIFIER, false)
}

#[inline]
pub fn pin_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PIN_IDENTIFIER, true)
}

#[inline]
pub fn finish_pin_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PIN<'a>>
) {
    fbb.finish(root, Some(PIN_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_pin_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PIN<'a>>
) {
    fbb.finish_size_prefixed(root, Some(PIN_IDENTIFIER));
}
